// the base action is propagated through `Result` unchanged.

internal
fun action431
(
    text: String,
    sym0: Triple<Int, List<Attribute>, Int>,
    sym1: Triple<Int, TerminalString, Int>,
    sym2: Triple<Int, String, Int>,
    sym3: Triple<Int, Int, Int>,
): Result<Conversion>
{
    val start0 = sym0.first
    val end0 = sym0.first
    val start1 = sym1.third
    val end1 = sym2.first
    val temp0 = action198(
        text,
        start0,
        end0,
    )
    val temp0Triple = Triple(start0, temp0, end0)
    val temp1 = action198(
        text,
        start1,
        end1,
    )
    val temp1Triple = Triple(start1, temp1, end1)
    return action102(
        text,
        temp0Triple,
        sym0,
        sym1,
        temp1Triple,
        sym2,
        sym3,
    )
}

